// src/App.js — khai báo MỌI route của CodeLearn ở một chỗ (nhìn là thấy cả sơ đồ trang)
import { Route, Routes } from 'react-router-dom';
import Layout from './components/Layout';
import HomePage from './pages/HomePage';
import CoursesPage from './pages/CoursesPage';
import NotFoundPage from './pages/NotFoundPage';
import ProtectedRoute from './components/ProtectedRoute';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import AdminLayout from './pages/admin/AdminLayout';
import CourseDetailPage from './pages/CourseDetailPage';
import MyCoursesPage from './pages/MyCoursesPage';
import LearnPage from './pages/LearnPage';
import QuizPage from './pages/QuizPage';

export default function App() {
  return (
    <Routes>
      {/* Layout chung: navbar + <Outlet /> + footer cho mọi trang */}
      <Route element={<Layout />}>
        {/* ── Khách (guest) xem được ── */}
        <Route path="/" element={<HomePage />} />
        <Route path="/courses" element={<CoursesPage />} />
        <Route path="/courses/:id" element={<CourseDetailPage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/register" element={<RegisterPage />} />

        {/* ── Phải đăng nhập (học viên) ── */}
        <Route element={<ProtectedRoute />}>
          <Route path="/my-courses" element={<MyCoursesPage />} />
          <Route path="/learn/:courseId" element={<LearnPage />} />
          <Route path="/learn/:courseId/lessons/:lessonId" element={<LearnPage />} />
          <Route path="/quiz/:chapterId" element={<QuizPage />} />
        </Route>

        {/* ── Chỉ ADMIN — route lồng: AdminLayout có sidebar + <Outlet /> ── */}
        <Route path="/admin" element={<ProtectedRoute role="admin"><AdminLayout /></ProtectedRoute>}>
        </Route>

        {/* Mọi đường dẫn không khớp ⇒ 404 (luôn để CUỐI) */}
        <Route path="*" element={<NotFoundPage />} />
      </Route>
    </Routes>
  );
}

// src/api/quizApi.js — questions + results (mọi hàm trả response.data)
// ⚠ json-server trả cả answerIndex về trình duyệt — máy chủ thật phải chấm ở server và giấu đáp án.
import axiosClient from './axiosClient';

const quizApi = {
  getChapter: (id) => axiosClient.get(`/chapters/${id}`).then((res) => res.data),
  getQuestions: (chapterId) => axiosClient.get('/questions', { params: { chapterId, _sort: 'id' } }).then((res) => res.data),
  saveResult: (result) => axiosClient.post('/results', result).then((res) => res.data),
};

export default quizApi;

// src/components/AppNavbar.js — thanh điều hướng; NavLink tự gắn class "active" cho trang đang mở
import { Button, Container, Nav, Navbar } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { Link, NavLink, useNavigate } from 'react-router-dom';
import { logout, selectUser } from '../features/auth/authSlice';

export default function AppNavbar() {
  const user = useSelector(selectUser);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const isStudent = user?.role === 'student';

  const handleLogout = () => {
    dispatch(logout());          // store.subscribe (app/store.js) sẽ xoá localStorage
    navigate('/', { replace: true });
  };

  return (
    <Navbar bg="dark" data-bs-theme="dark" expand="md" sticky="top">
      <Container>
        <Navbar.Brand as={Link} to="/" id="brand">💻 CodeLearn</Navbar.Brand>
        <Navbar.Toggle aria-controls="main-nav" />
        <Navbar.Collapse id="main-nav">
          <Nav className="me-auto">
            {/* end: "/" chỉ active đúng ở trang chủ, không active ở mọi trang */}
            <Nav.Link as={NavLink} to="/" end id="nav-home">Home</Nav.Link>
            <Nav.Link as={NavLink} to="/courses" id="nav-courses">Courses</Nav.Link>
            {isStudent && <Nav.Link as={NavLink} to="/my-courses" id="nav-my-courses">My Courses</Nav.Link>}
            {user?.role === 'admin' && <Nav.Link as={NavLink} to="/admin" id="nav-admin">Admin</Nav.Link>}
          </Nav>
          <Nav className="align-items-md-center gap-2">
            {user ? (
              <>
                <Navbar.Text id="nav-user">Hi, {user.fullName}</Navbar.Text>
                <Button id="logout-btn" size="sm" variant="outline-light" onClick={handleLogout}>Log out</Button>
              </>
            ) : (
              <>
                <Nav.Link as={NavLink} to="/login" id="nav-login">Log in</Nav.Link>
                <Nav.Link as={NavLink} to="/register" id="nav-register">Register</Nav.Link>
              </>
            )}
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

// src/features/quiz/quizSlice.js — làm quiz cuối chương: tải câu hỏi, giữ câu trả lời, chấm + lưu kết quả
import { createAsyncThunk, createSlice } from '@reduxjs/toolkit';
import quizApi from '../../api/quizApi';
import { logout } from '../auth/authSlice';
import { scoreQuiz } from '../../utils/learning';

export const fetchQuiz = createAsyncThunk('quiz/fetch', async (chapterId, { rejectWithValue }) => {
  try {
    const [chapter, questions] = await Promise.all([quizApi.getChapter(chapterId), quizApi.getQuestions(chapterId)]);
    return { chapter, questions };
  } catch (err) {
    if (err.response?.status === 404) return rejectWithValue('notFound');
    throw err;
  }
});

// chấm ở client (json-server không chấm được), rồi LƯU kết quả — chỉ hiện điểm khi đã lưu xong
export const submitQuiz = createAsyncThunk('quiz/submit', async ({ userId }, { getState }) => {
  const { chapter, questions, answers } = getState().quiz;
  const { score, total, percent, passed } = scoreQuiz(questions, answers);
  return quizApi.saveResult({
    userId,
    courseId: chapter.courseId,
    chapterId: chapter.id,
    score,
    total,
    percent,
    passed,
    answers: questions.map((q) => answers[q.id]),
    submittedAt: new Date().toISOString(),
  });
});

const initialState = {
  chapter: null,
  questions: [],
  answers: {},          // { [questionId]: optionIndex }
  result: null,         // bản ghi results vừa lưu
  status: 'idle',
  error: null,
  submitStatus: 'idle',
};

const quizSlice = createSlice({
  name: 'quiz',
  initialState,
  reducers: {
    answerSelected(state, action) {
      if (state.result) return;                    // đã nộp ⇒ khoá câu trả lời
      const { questionId, optionIndex } = action.payload;
      state.answers[questionId] = optionIndex;
    },
    retakeQuiz(state) {
      state.answers = {};
      state.result = null;
      state.submitStatus = 'idle';
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchQuiz.pending, (state) => {
        // làm bài mới ⇒ bỏ câu trả lời / điểm của chương trước
        Object.assign(state, { chapter: null, questions: [], answers: {}, result: null, status: 'loading', error: null, submitStatus: 'idle' });
      })
      .addCase(fetchQuiz.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.chapter = action.payload.chapter;
        state.questions = action.payload.questions;
      })
      .addCase(fetchQuiz.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.payload ?? action.error.message;
      })
      .addCase(submitQuiz.pending, (state) => {
        state.submitStatus = 'loading';
      })
      .addCase(submitQuiz.fulfilled, (state, action) => {
        state.submitStatus = 'succeeded';
        state.result = action.payload;
      })
      .addCase(submitQuiz.rejected, (state) => {
        state.submitStatus = 'failed';
      })
      .addCase(logout, () => initialState);
  },
});

export const { answerSelected, retakeQuiz } = quizSlice.actions;
export default quizSlice.reducer;

