// src/api/authApi.js — bảng users trên json-server (mọi hàm trả response.data)
// ⚠ json-server KHÔNG phải máy chủ xác thực thật: mật khẩu nằm trần trong db.json — chỉ để học.
import axiosClient from './axiosClient';

const authApi = {
  // GET /users?email=... — json-server lọc khớp CHÍNH XÁC (phân biệt hoa/thường) ⇒ luôn lưu & tìm email chữ thường
  findByEmail: (email) => axiosClient.get('/users', { params: { email } }).then((res) => res.data),
  create: (user) => axiosClient.post('/users', user).then((res) => res.data),
};

export default authApi;

// src/api/axiosClient.js — MỘT chỗ duy nhất biết địa chỉ API (ĐÃ CHO SẴN)
// Đọc từ .env (REACT_APP_API_URL) — không viết cứng "http://localhost:9999" ở bất kỳ đâu khác.
// ⚠ CRA chỉ đọc .env lúc `npm start` khởi động: sửa .env thì phải tắt và chạy lại.
import axios from 'axios';

const axiosClient = axios.create({
  baseURL: process.env.REACT_APP_API_URL,
  headers: { 'Content-Type': 'application/json' },
  timeout: 10000,
});

// Quy ước của dự án: mỗi hàm trong src/api/*.js tự trả `response.data`
// (không dựa vào interceptor để "bóc" data — đọc code là thấy ngay hàm trả gì).
export default axiosClient;

// src/api/courseApi.js — categories / courses / chapters / lessons (mọi hàm trả response.data)
import axiosClient from './axiosClient';

const courseApi = {
  getCategories: () => axiosClient.get('/categories').then((res) => res.data),
  // học viên/khách chỉ thấy khoá đã xuất bản (published=true) — lọc ở MÁY CHỦ
  getPublishedCourses: () => axiosClient.get('/courses', { params: { published: true } }).then((res) => res.data),
  getCourse: (id) => axiosClient.get(`/courses/${id}`).then((res) => res.data),
  // chương của khoá + bài học lồng bên trong bằng _embed (json-server 0.17: con có khoá chapterId)
  getCurriculum: (courseId) =>
    axiosClient.get('/chapters', { params: { courseId, _embed: 'lessons', _sort: 'order', _order: 'asc' } }).then((res) => res.data),
  // tổng bài học của NHIỀU khoá trong một lần gọi: /lessons?courseId=1&courseId=3 (json-server hiểu là "hoặc")
  getLessonsOfCourses: (courseIds) =>
    axiosClient.get(`/lessons?${courseIds.map((id) => `courseId=${id}`).join('&')}`).then((res) => res.data),
};

export default courseApi;

// src/api/enrollApi.js — bảng enrollments (mọi hàm trả response.data)
import axiosClient from './axiosClient';

const enrollApi = {
  // đăng ký của một học viên + thông tin khoá (_expand=course ⇒ mỗi bản ghi có thêm .course), mới nhất trước
  getByUser: (userId) =>
    axiosClient.get('/enrollments', { params: { userId, _expand: 'course', _sort: 'enrolledAt', _order: 'desc' } }).then((res) => res.data),
  find: (userId, courseId) => axiosClient.get('/enrollments', { params: { userId, courseId } }).then((res) => res.data),
  create: (enrollment) => axiosClient.post('/enrollments', enrollment).then((res) => res.data),
  // PATCH CHỈ trường đổi — PUT cả object sẽ ghi luôn trường "course" đã _expand vào db.json
  updateProgress: (id, completedLessons) => axiosClient.patch(`/enrollments/${id}`, { completedLessons }).then((res) => res.data),
};

export default enrollApi;

// src/app/store.js — store Redux duy nhất của app: mỗi "feature" một slice
import { configureStore } from '@reduxjs/toolkit';
import authReducer, { STORAGE_KEY } from '../features/auth/authSlice';
import coursesReducer from '../features/courses/coursesSlice';
import enrollmentsReducer from '../features/enrollments/enrollmentsSlice';
import quizReducer from '../features/quiz/quizSlice';

export const store = configureStore({
  reducer: {
    auth: authReducer,
    courses: coursesReducer,
    enrollments: enrollmentsReducer,
    quiz: quizReducer,
  },
});

// Lưu phiên đăng nhập NGOÀI reducer (reducer phải thuần — không đụng localStorage).
// Chỉ ghi khi user thật sự đổi (đăng nhập / đăng ký / đăng xuất), không ghi lại ở mọi action.
let lastUser = store.getState().auth.user;
store.subscribe(() => {
  const { user } = store.getState().auth;
  if (user === lastUser) return;
  lastUser = user;
  if (user) localStorage.setItem(STORAGE_KEY, JSON.stringify(user));
  else localStorage.removeItem(STORAGE_KEY);
});

export default store;

// src/components/CourseCard.js — thẻ một khoá học (component trình bày: chỉ nhận props, không gọi API)
import { Badge, Card } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { formatPrice } from '../utils/format';

const LEVEL_COLOR = { Beginner: 'success', Intermediate: 'warning', Advanced: 'danger' };

// "React for Beginners" ⇒ "RB" — ảnh thay thế khi khoá chưa có thumbnail
const initials = (title) => title.split(/\s+/).filter((w) => /^[A-Za-z]/.test(w)).slice(0, 2).map((w) => w[0].toUpperCase()).join('');

export default function CourseCard({ course, categoryName }) {
  return (
    <Card className="course-card h-100 shadow-sm" id={`course-${course.id}`}>
      {course.thumbnail ? (
        <Card.Img variant="top" src={course.thumbnail} alt={course.title} style={{ height: 130, objectFit: 'cover' }} />
      ) : (
        <div className="course-thumb" aria-hidden="true">{initials(course.title)}</div>
      )}
      <Card.Body>
        <div className="d-flex gap-2 mb-2">
          <Badge bg="info" className="course-category">{categoryName}</Badge>
          <Badge bg={LEVEL_COLOR[course.level] ?? 'secondary'} className="course-level">{course.level}</Badge>
        </div>
        <Card.Title className="course-title fs-6 fw-bold">{course.title}</Card.Title>
        <Card.Text className="course-instructor text-muted small">by {course.instructor}</Card.Text>
      </Card.Body>
      <Card.Footer className="bg-white d-flex justify-content-between align-items-center">
        <span className="course-price fw-bold">{formatPrice(course.price)}</span>
        <Link to={`/courses/${course.id}`} className="btn btn-sm btn-primary btn-detail">View details</Link>
      </Card.Footer>
    </Card>
  );
}

